mapper.select:
SELECT FROM products p JOIN categories c ON c.id = p.category_id LEFT JOIN brands b ON b.id = p.brand_id LEFT JOIN skus s ON s.product_id = p.id AND s.deleted_at IS NULL LEFT JOIN product_images pi ON pi.product_id = p.id LEFT JOIN files f ON f.id = pi.file_id
p.deleted_at IS NULL AND p.status = 'ACTIVE' AND c.status = 'ACTIVE' AND c.deleted_at IS NULL AND (b.id IS NULL OR (b.status = 'ACTIVE' AND b.deleted_at IS NULL)) AND p.status = #{status} AND p.category_id = #{categoryId} AND c.slug = #{categorySlug} AND p.brand_id = #{brandId} AND b.slug = #{brandSlug} AND p.gender = #{gender} AND (p.name ILIKE CONCAT('%', #{keyword}, '%') OR p.short_description ILIKE CONCAT('%', #{keyword}, '%')) AND p.is_featured = true AND EXISTS (SELECT 1 FROM skus sx JOIN sizes sz ON sz.id = sx.size_id WHERE sx.product_id=p.id AND sx.deleted_at IS NULL AND sz.value=#{size}) AND EXISTS (SELECT 1 FROM product_variants vx JOIN colors cx ON cx.id = vx.color_id WHERE vx.product_id=p.id AND vx.deleted_at IS NULL AND (cx.name ILIKE CONCAT('%', #{color}, '%') OR cx.color_code ILIKE CONCAT('%', #{color}, '%') OR vx.name ILIKE CONCAT('%', #{color}, '%'))) AND EXISTS (SELECT 1 FROM skus sp WHERE sp.product_id=p.id AND sp.deleted_at IS NULL AND COALESCE(sp.sale_price, sp.price) >= #{minPrice}) AND EXISTS (SELECT 1 FROM skus sp WHERE sp.product_id=p.id AND sp.deleted_at IS NULL AND COALESCE(sp.sale_price, sp.price) <= #{maxPrice})
GROUP BY p.id, c.name, b.name, b.slug ORDER BY p.featured_order ASC, p.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE product_variants SET deleted_at=now()
WHERE product_id=#{productId} AND deleted_at IS NULL

    AND id::text NOT IN #{id}

UPDATE product_variants
SET name=#{name}, color_id=#{colorId}, image_file_id=#{imageFileId}, status=#{status}, sort_order=#{sortOrder}
WHERE id=#{id} AND product_id=#{productId} AND deleted_at IS NULL

UPDATE skus SET deleted_at=now()
WHERE product_id=#{productId} AND deleted_at IS NULL

    AND id::text NOT IN #{id}

UPDATE skus
SET variant_id=#{variantId}, sku_code=#{skuCode}, size_id=#{sizeId}, price=#{price}, sale_price=#{salePrice}, stock=#{stock}, status=#{status}
WHERE id=#{id} AND product_id=#{productId} AND deleted_at IS NULL
